use vstd::prelude::*;

verus! {

fn nanmin(a: Vec<i8>) -> (result: i8)
    requires
        a.len() > 0,
    ensures
        // result is an element of the array
        exists|k: int| 0 <= k < a.len() && result == a[k],
        // result is <= every element of the array
        forall|k: int| 0 <= k < a.len() ==> result <= a[k],
{
    let mut i: usize = 1;
    let mut m: i8 = a[0];

    while i < a.len()
        invariant
            1 <= i <= a.len(),
            // m is some element among the prefix a[0..i)
            exists|k: int| 0 <= k < i && m == a[k],
            // m is <= every element among the prefix a[0..i)
            forall|k: int| 0 <= k < i ==> m <= a[k],
        decreases
            a.len() - i,
    {
        let x = a[i];
        if x < m {
            m = x;
        }
        i = i + 1;
    }

    result = m;
}

} // verus!

